// Extract and clean text content from Google Docs
const docData = $input.first().json;

// Extract title (first heading or document title)
let title = '';
let content = '';

// Process document content
if (docData.body && docData.body.content) {
  const elements = docData.body.content;

  for (const element of elements) {
    if (element.paragraph) {
      const paragraph = element.paragraph;
      let paragraphText = '';

      if (paragraph.elements) {
        for (const textElement of paragraph.elements) {
          if (textElement.textRun && textElement.textRun.content) {
            paragraphText += textElement.textRun.content;
          }
        }
      }

      // First substantial paragraph becomes title if not set
      if (!title && paragraphText.trim().length > 5) {
        title = paragraphText.trim();
      } else if (paragraphText.trim()) {
        content += paragraphText.trim() + '\n\n';
      }
    }
  }
}

// Clean up content
content = content.trim();

// Fallback title
if (!title) {
  title = docData.title || 'Untitled Document';
}

return {
  originalTitle: title,
  rawContent: content,
  documentId: docData.documentId,
  wordCount: content.split(' ').length
};

// Parse AI response and combine with content
const aiResponse = $input.first().json.message.content;
const extractedData = $('Extract Content').first().json;

let seoData;
try {
  // Remove any markdown code blocks if present
  const cleanResponse = aiResponse.replace(/```json\n?|```\n?/g, '').trim();
  seoData = JSON.parse(cleanResponse);
} catch (error) {
  console.log('Error parsing AI response:', error);
  console.log('AI Response:', aiResponse);

  // Fallback SEO data
  seoData = {
    optimizedTitle: extractedData.originalTitle,
    metaDescription: extractedData.rawContent.substring(0, 150) + '...',
    excerpt: extractedData.rawContent.substring(0, 200) + '...',
    categories: ['Stoic Philosophy', 'Daily Practice'],
    tags: ['stoicism', 'philosophy', 'wisdom'],
    slug: extractedData.originalTitle.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''),
    suggestedFeaturedImage: 'Ancient Greek or Roman philosophical scene'
  };
}

// Generate current timestamp
const now = new Date().toISOString();

// Create slug if not provided
if (!seoData.slug) {
  seoData.slug = seoData.optimizedTitle.toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
    .substring(0, 96);
}

// Convert content to basic Portable Text blocks
const contentBlocks = [];
const paragraphs = extractedData.rawContent.split('\n\n');

for (const paragraph of paragraphs) {
  if (paragraph.trim()) {
    contentBlocks.push({
      _type: 'block',
      _key: 'block_' + Math.random().toString(36).substr(2, 9),
      style: 'normal',
      children: [{
        _type: 'span',
        _key: 'span_' + Math.random().toString(36).substr(2, 9),
        text: paragraph.trim(),
        marks: []
      }],
      markDefs: []
    });
  }
}

return {
  title: seoData.optimizedTitle,
  slug: {
    _type: 'slug',
    current: seoData.slug
  },
  author: 'Content Team',
  excerpt: seoData.excerpt,
  categories: seoData.categories,
  tags: seoData.tags,
  publishedAt: now,
  body: contentBlocks,
  featured: false,
  seo: {
    metaTitle: seoData.optimizedTitle,
    metaDescription: seoData.metaDescription
  },
  _type: 'blogPost',
  suggestedFeaturedImage: seoData.suggestedFeaturedImage,
  originalDocumentId: extractedData.documentId
};

// Process the Sanity API response
const sanityResponse = $input.first().json;

if (sanityResponse.results && sanityResponse.results.length > 0) {
  const result = sanityResponse.results[0];

  if (result.operation === 'create' && result.document) {
    const doc = result.document;

    return {
      success: true,
      message: 'Blog post created successfully!',
      documentId: doc._id,
      title: doc.title,
      slug: doc.slug.current,
      publishedAt: doc.publishedAt,
      studioUrl: `https://{{ $env.SANITY_PROJECT_ID }}.sanity.studio/structure/blogPost;${doc._id}`,
      blogUrl: `https://your-domain.com/blog/${doc.slug.current}`,
      suggestedFeaturedImage: doc.suggestedFeaturedImage || 'No suggestion provided'
    };
  }
}

// Handle errors
return {
  success: false,
  message: 'Failed to create blog post',
  error: sanityResponse.error || 'Unknown error',
  response: sanityResponse
};
